let ok = 0, mal = 0
for (const [id, sol] of Object.entries(SOLUCIONS)) {
  const g = await j('GET', '/nodo/' + encodeURIComponent(id)); if (g.status !== 200) { console.log('GET', id, g.status); mal++; continue }
  const n = g.data
  const body = { type: n.type, status: n.status, relevance: n.relevance, difficulty: n.difficulty, autor: n.autor || '', centro: n.centro || '', reto_bloqueado: false, reto_puntos: n.reto_puntos || 10 }
  if (sol.secondary) body.solucion_secondary = sol.secondary
  if (sol.expert) body.solucion_expert = sol.expert
  for (const l of n.idiomas || ['gl', 'es', 'en', 'pt']) {
    body[`label_${l}`] = n.labels?.[l] || ''
    for (const niv of ['primary', 'secondary', 'expert']) { body[`text_${niv}_${l}`] = n.content?.[niv]?.[l] || ''; body[`reto_${niv}_${l}`] = n.retos?.[niv]?.[l] || '' }
  }
  const p = await j('PUT', '/nodo/' + encodeURIComponent(id), body, TOKEN)
  if (p.status === 200) ok++; else { mal++; console.log('PUT', id, p.status, p.data) }
}
console.log('solucións gardadas:', ok, '| erros:', mal)
